  e_no_tx: ["This sensor has no TX pin set, so it cannot be configured.", "Este sensor no tiene pin TX, así que no se puede configurar.", "Für diesen Sensor ist kein TX-Pin gesetzt, er kann nicht konfiguriert werden.", "Ce capteur n'a pas de broche TX, il ne peut pas être configuré.", "Questo sensore non ha il pin TX, non può essere configurato.", "このセンサーにはTXピンがなく、設定できません。", "此传感器没有设置TX引脚，无法配置。"],
  e_disabled: ["This sensor is disabled.", "Este sensor está desactivado.", "Dieser Sensor ist deaktiviert.", "Ce capteur est désactivé.", "Questo sensore è disattivato.", "このセンサーは無効です。", "此传感器已禁用。"],
  e_busy: ["The sensor is busy with another command.", "El sensor está ocupado con otro comando.", "Der Sensor ist mit einem anderen Befehl beschäftigt.", "Le capteur est occupé par une autre commande.", "Il sensore è occupato con un altro comando.", "センサーは別のコマンドを処理中です。", "传感器正忙于另一个命令。"],
  e_no_answer: ["The module did not answer (check the TX wire, the power and the speed).", "El módulo no respondió (revisa el cable TX, la alimentación y la velocidad).", "Das Modul antwortete nicht (prüfe TX-Leitung, Spannung und Geschwindigkeit).", "Le module n'a pas répondu (vérifiez le fil TX, l'alimentation et la vitesse).", "Il modulo non ha risposto (controlla il filo TX, l'alimentazione e la velocità).", "モジュールが応答しません（TX配線、電源、速度を確認）。", "模块没有应答（请检查TX线、电源和速度）。"],
  e_refused: ["The module refused the command.", "El módulo rechazó el comando.", "Das Modul hat den Befehl abgelehnt.", "Le module a refusé la commande.", "Il modulo ha rifiutato il comando.", "モジュールがコマンドを拒否しました。", "模块拒绝了该命令。"],
  e_bad_argument: ["The values are not valid.", "Los valores no son válidos.", "Die Werte sind ungültig.", "Les valeurs ne sont pas valides.", "I valori non sono validi.", "値が正しくありません。", "数值无效。"],
