  baudModel: ["the model's own ({0})", "la propia del modelo ({0})", "die des Modells ({0})", "celle du modèle ({0})", "quella del modello ({0})", "モデル標準（{0}）", "型号默认（{0}）"],
  deviceName: ["Device name", "Nombre del dispositivo", "Gerätename", "Nom de l'appareil", "Nome del dispositivo", "デバイス名", "设备名称"],
  deviceNameHint: ["A presence sensor is a device of the server with this name: lowercase letters, digits, - and _ (it cannot repeat a pin's name).", "Un sensor de presencia es un dispositivo del servidor con este nombre: minúsculas, dígitos, - y _ (no puede repetir el de un pin).", "Ein Anwesenheitssensor ist ein Gerät des Servers mit diesem Namen: Kleinbuchstaben, Ziffern, - und _ (nicht der Name eines Pins).", "Un capteur de présence est un appareil du serveur portant ce nom : minuscules, chiffres, - et _ (pas celui d'une broche).", "Un sensore di presenza è un dispositivo del server con questo nome: minuscole, cifre, - e _ (non può ripetere quello di un pin).", "在席センサーはこの名前のサーバーのデバイスになります：小文字、数字、-、_（ピン名と重複不可）。", "存在传感器是服务器上使用此名称的设备：小写字母、数字、- 和 _（不能与引脚名称重复）。"],
  kindTracker: ["gives positions: it feeds the perimeter's radar", "da posiciones: alimenta el radar del perímetro", "liefert Positionen: speist das Radar des Perimeters", "donne des positions : alimente le radar du périmètre", "dà posizioni: alimenta il radar del perimetro", "位置を出力：境界のレーダーに使われます", "提供位置：用于周界雷达"],
  kindPresence: ["gives presence and distance: it becomes a device of the server", "da presencia y distancia: se convierte en un dispositivo del servidor", "liefert Anwesenheit und Abstand: wird ein Gerät des Servers", "donne présence et distance : devient un appareil du serveur", "dà presenza e distanza: diventa un dispositivo del server", "在席と距離を出力：サーバーのデバイスになります", "提供存在与距离：成为服务器上的设备"],
